insert into topic_contents (topic_id, summary, content_md, example_question) values ('c876132a-c63c-4a00-bc2b-f40f32d682d6', 'Büyük Hun İmparatorluğu, Avrupa Hun Devleti, Göktürk Devleti ve Uygur Devleti İslamiyet öncesi Türk tarihinin temel devletleridir. Kut inancı, ikili (doğu-batı) teşkilat yapısı ve konargöçer yaşam tarzı bu devletlerin ortak özellikleridir; Uygurların yerleşik hayata geçip Mani dinini benimsemesi ise bu genel örüntünün istisnasıdır.', '## Büyük Hun İmparatorluğu
insert into questions (id, topic_id, difficulty, question_text, kazanim, explanation) values ('0239fcbc-0ae6-40b8-9f3c-47ad7d0cd8c3', 'c876132a-c63c-4a00-bc2b-f40f32d682d6', 'kolay'::difficulty_level, 'Onlu (ondalık) askeri-idari teşkilatı kurarak sonraki Türk devletlerine örnek olan hükümdar aşağıdakilerden hangisidir?', 'Büyük Hun İmparatorluğu''nun teşkilat yapısını bilir.', 'Mete Han, MÖ 209''da Büyük Hun İmparatorluğu''nda onlu askeri-idari teşkilatı kurmuş ve bu düzen kendisinden sonraki tüm Türk devletlerine örnek olmuştur (C doğru). Bilge Kağan (A) ve Kültigin (B) Göktürk dönemi hükümdarlarındandır. Attila (D) Avrupa Hun Devleti hükümdarıdır. Bumin Kağan (E) Göktürk Devleti''nin kurucusudur.');
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('0239fcbc-0ae6-40b8-9f3c-47ad7d0cd8c3', 'Bilge Kağan', false, 0);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('0239fcbc-0ae6-40b8-9f3c-47ad7d0cd8c3', 'Kültigin', false, 1);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('0239fcbc-0ae6-40b8-9f3c-47ad7d0cd8c3', 'Mete Han', true, 2);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('0239fcbc-0ae6-40b8-9f3c-47ad7d0cd8c3', 'Attila', false, 3);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('0239fcbc-0ae6-40b8-9f3c-47ad7d0cd8c3', 'Bumin Kağan', false, 4);
insert into questions (id, topic_id, difficulty, question_text, kazanim, explanation) values ('088b308c-9a94-4cf5-a5b5-cb5cf7b2e96a', 'c876132a-c63c-4a00-bc2b-f40f32d682d6', 'orta'::difficulty_level, 'Türk adının geçtiği ilk yazılı Türkçe kaynak aşağıdakilerden hangisidir?', 'Orhun Anıtları''nın önemini bilir.', 'Orhun Anıtları (Bilge Kağan, Kültigin ve Vezir Tonyukuk adına dikilen), Türk adının geçtiği ilk yazılı Türkçe belgelerdir (B doğru). Kutadgu Bilig (A) Karahanlı dönemine ait bir siyasetname eseridir. Divan-ı Lügati''t Türk (C) ve Divan-ı Hikmet (D) de İslamiyet sonrası dönem eserleridir. Uygur alfabesiyle yazılmış metinler (E) Orhun Anıtları''ndan sonra ortaya çıkmıştır.');
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('088b308c-9a94-4cf5-a5b5-cb5cf7b2e96a', 'Kutadgu Bilig', false, 0);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('088b308c-9a94-4cf5-a5b5-cb5cf7b2e96a', 'Orhun Anıtları', true, 1);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('088b308c-9a94-4cf5-a5b5-cb5cf7b2e96a', 'Divan-ı Lügati''t Türk', false, 2);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('088b308c-9a94-4cf5-a5b5-cb5cf7b2e96a', 'Divan-ı Hikmet', false, 3);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('088b308c-9a94-4cf5-a5b5-cb5cf7b2e96a', 'Uygur dönemi metinleri', false, 4);
insert into questions (id, topic_id, difficulty, question_text, kazanim, explanation) values ('92fdd507-514d-4618-83b9-0e4e9a81fa10', 'c876132a-c63c-4a00-bc2b-f40f32d682d6', 'orta'::difficulty_level, 'Kavimler Göçü''nün (375) sonuçlarıyla ilgili aşağıdaki bilgilerden hangisi doğrudur?', 'Kavimler Göçü''nün Avrupa tarihine etkisini bilir.', 'Kavimler Göçü, Avrupa''da köklü değişikliklere yol açmış; Roma İmparatorluğu 395''te Doğu ve Batı olmak üzere ikiye ayrılmış, göç sonucu oluşan karışıklık ortamı Avrupa''da feodalitenin (derebeylik rejiminin) doğmasına zemin hazırlamıştır (C doğru). A yanlıştır, göçü BAŞLATAN Avrupa Hunlarıdır, Çin değildir. B yanlıştır, İslamiyet bu tarihte henüz doğmamıştı (610''da doğdu). D yanlıştır, göç Roma''yı güçlendirmemiş, aksine yıkılış sürecini hızlandırmıştır. E yanlıştır, Kavimler Göçü''nü Türkler (Hunlar) başlatmıştır, Germen kavimleri göçe bu baskı sonucunda katılmıştır.');
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('92fdd507-514d-4618-83b9-0e4e9a81fa10', 'Çin, kuzeyden gelen bu göçü başlatmıştır.', false, 0);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('92fdd507-514d-4618-83b9-0e4e9a81fa10', 'İslamiyet bu göç sırasında Arabistan''da doğmuştur.', false, 1);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('92fdd507-514d-4618-83b9-0e4e9a81fa10', 'Roma İmparatorluğu ikiye ayrılmış ve Avrupa''da feodalite doğmuştur.', true, 2);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('92fdd507-514d-4618-83b9-0e4e9a81fa10', 'Bu göç, Roma İmparatorluğu''nu güçlendirmiştir.', false, 3);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('92fdd507-514d-4618-83b9-0e4e9a81fa10', 'Göçü başlatan kavim Germenlerdir.', false, 4);
insert into questions (id, topic_id, difficulty, question_text, kazanim, explanation) values ('b20f3b98-7728-4f63-9f63-70a305f1edf6', 'c876132a-c63c-4a00-bc2b-f40f32d682d6', 'zor'::difficulty_level, 'Türk devletlerinde görülen ''kut'' inancıyla ilgili aşağıdaki yargılardan hangisi doğrudur?', 'Kut inancının siyasi sonuçlarını değerlendirir.', 'Kut inancına göre yönetme yetkisi Gök Tanrı tarafından hükümdara ve hanedanın tüm erkek üyelerine verilmiş kabul edildiğinden, bu durum taht kavgalarına ve devletlerin kısa sürede parçalanmasına zemin hazırlamıştır (B doğru). A yanlıştır, kut yalnızca hükümdara değil hanedan üyelerine de verilmiş sayılırdı, bu da sorunun kaynağıydı. C yanlıştır, kut dini değil siyasi-yönetsel bir meşruiyet kaynağıdır. D yanlıştır, kut inancı devlet birliğini SAĞLAMLAŞTIRMAMIŞ, tam tersine parçalanmaya yol açmıştır. E yanlıştır, bu inanç yalnızca bir devlete özgü değil, ortak Türk devlet geleneğinin bir parçasıdır.');
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('b20f3b98-7728-4f63-9f63-70a305f1edf6', 'Kut, yalnızca hükümdarın kendisine verilmiş, hanedanın diğer üyelerini kapsamazdı.', false, 0);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('b20f3b98-7728-4f63-9f63-70a305f1edf6', 'Kut inancı, hanedan üyeleri arasında taht kavgalarına ve devletlerin parçalanmasına zemin hazırlamıştır.', true, 1);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('b20f3b98-7728-4f63-9f63-70a305f1edf6', 'Kut, dinî bir kavram olup siyasi bir sonuç doğurmamıştır.', false, 2);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('b20f3b98-7728-4f63-9f63-70a305f1edf6', 'Kut inancı, Türk devletlerinde birliği güçlendirmiş ve iç kargaşayı önlemiştir.', false, 3);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('b20f3b98-7728-4f63-9f63-70a305f1edf6', 'Kut inancı yalnızca Uygur Devleti''ne özgüdür.', false, 4);
insert into topic_contents (topic_id, summary, content_md, example_question) values ('145d44b3-a8e7-430f-8778-71fb8929a97d', 'Osman Bey''in beyliği devlete dönüştürmesinden başlayarak Orhan Bey''in kurumsallaşma adımları (ilk düzenli ordu, ilk medrese), I. Murad döneminde merkezi teşkilatın (yeniçeri ocağı, kapıkulu) oluşması, Yıldırım Bayezıd döneminde Ankara Savaşı ve Fetret Devri, son olarak Çelebi Mehmed ve II. Murad döneminde devletin yeniden toparlanması bu konunun kronolojik omurgasını oluşturur.', '## Osman Bey Dönemi (Beylikten Devlete Geçiş)
insert into questions (id, topic_id, difficulty, question_text, kazanim, explanation) values ('27372e6f-3385-4e4f-bf19-21cde1072b70', '145d44b3-a8e7-430f-8778-71fb8929a97d', 'kolay'::difficulty_level, 'Osmanlı Beyliği''nin bağımsızlığını ilan ederek devletin kurucusu kabul edilen hükümdar aşağıdakilerden hangisidir?', 'Osmanlı Devleti''nin kuruluşunu bilir.', 'Osman Bey, 1299''da bağımsızlığını ilan ederek Osmanlı Beyliği''ni kurmuştur (A doğru). Orhan Bey (B) Osman Bey''in oğludur ve kurumsallaşmayı başlatmıştır. I. Murad (C), Yıldırım Bayezıd (D) ve Çelebi Mehmed (E) kuruluştan sonraki dönemlerde tahta çıkmış hükümdarlardır.');
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('27372e6f-3385-4e4f-bf19-21cde1072b70', 'Osman Bey', true, 0);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('27372e6f-3385-4e4f-bf19-21cde1072b70', 'Orhan Bey', false, 1);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('27372e6f-3385-4e4f-bf19-21cde1072b70', 'I. Murad', false, 2);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('27372e6f-3385-4e4f-bf19-21cde1072b70', 'Yıldırım Bayezıd', false, 3);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('27372e6f-3385-4e4f-bf19-21cde1072b70', 'Çelebi Mehmed', false, 4);
insert into questions (id, topic_id, difficulty, question_text, kazanim, explanation) values ('08f7ec6f-6618-4d63-a049-b9d8f39bf6c7', '145d44b3-a8e7-430f-8778-71fb8929a97d', 'orta'::difficulty_level, 'Kapıkulu Ocakları ve Yeniçeri Ocağı''nın kurulduğu dönem aşağıdakilerden hangisidir?', 'Merkezi teşkilatın oluşum dönemini bilir.', 'Kapıkulu Ocakları ve Yeniçeri Ocağı, devşirme (pençik) sistemiyle asker temin edilmesi yoluyla I. MURAD (Hüdavendigâr) döneminde kurulmuştur (C doğru). Osman Bey (A) ve Orhan Bey (B) döneminde henüz bu kurumlar oluşmamıştı; Orhan Bey döneminde sadece Yaya-Müsellem birlikleri vardı. Yıldırım Bayezıd (D) ve Çelebi Mehmed (E) bu kurumların kurulmasından sonraki dönemlerdir.');
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('08f7ec6f-6618-4d63-a049-b9d8f39bf6c7', 'Osman Bey', false, 0);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('08f7ec6f-6618-4d63-a049-b9d8f39bf6c7', 'Orhan Bey', false, 1);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('08f7ec6f-6618-4d63-a049-b9d8f39bf6c7', 'I. Murad', true, 2);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('08f7ec6f-6618-4d63-a049-b9d8f39bf6c7', 'Yıldırım Bayezıd', false, 3);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('08f7ec6f-6618-4d63-a049-b9d8f39bf6c7', 'Çelebi Mehmed', false, 4);
insert into questions (id, topic_id, difficulty, question_text, kazanim, explanation) values ('f2bd33f3-4955-42b4-8a3b-8bbd2ef847f8', '145d44b3-a8e7-430f-8778-71fb8929a97d', 'orta'::difficulty_level, '1402 Ankara Savaşı''nın temel nedeni aşağıdakilerden hangisidir?', 'Ankara Savaşı''nın nedenini bilir.', 'Yıldırım Bayezıd''ın Anadolu Türk siyasi birliğini sağlamak amacıyla Anadolu beyliklerini Osmanlı topraklarına katma politikası, bu beyliklere sığınan beylerin Timur''dan yardım istemesiyle Timur ile Osmanlı''yı karşı karşıya getirmiştir (B doğru). A yanlıştır, savaşın nedeni bir Balkan meselesi değildir. C yanlıştır, Fetret Devri savaşın NEDENİ değil SONUCUDUR. D yanlıştır, bu dönemde henüz İstanbul kuşatılmamıştı bu amaçla. E yanlıştır, savaşın doğrudan nedeni dinî değil siyasi-topraksal bir çekişmedir.');
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('f2bd33f3-4955-42b4-8a3b-8bbd2ef847f8', 'Osmanlı''nın Balkanlardaki topraklarını genişletme isteği', false, 0);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('f2bd33f3-4955-42b4-8a3b-8bbd2ef847f8', 'Yıldırım Bayezıd''ın Anadolu Türk birliğini sağlama politikasının Timur ile çıkar çatışmasına yol açması', true, 1);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('f2bd33f3-4955-42b4-8a3b-8bbd2ef847f8', 'Fetret Devri''nin başlamış olması', false, 2);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('f2bd33f3-4955-42b4-8a3b-8bbd2ef847f8', 'İstanbul''un fethedilmek istenmesi', false, 3);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('f2bd33f3-4955-42b4-8a3b-8bbd2ef847f8', 'Dini bir anlaşmazlığın ortaya çıkması', false, 4);
insert into questions (id, topic_id, difficulty, question_text, kazanim, explanation) values ('f0b9bf6b-fa68-4291-820b-8d8d2ca9adda', '145d44b3-a8e7-430f-8778-71fb8929a97d', 'zor'::difficulty_level, 'Fetret Devri (1402-1413) ile ilgili aşağıdaki bilgilerden hangisi doğrudur?', 'Fetret Devri''nin nedenini ve sonucunu değerlendirir.', 'Fetret Devri, Ankara Savaşı''nda Yıldırım Bayezıd''ın esir düşmesi SONUCUNDA ortaya çıkmış, şehzadeler arası taht kavgalarıyla geçen bir dönemdir ve Çelebi Mehmed''in 1413''te tahtı ele geçirmesiyle sona ermiştir (D doğru). A yanlıştır, bu dönem Osmanlı''nın GÜÇLENDİĞİ değil ZAYIFLADIĞI bir dönemdir. B yanlıştır, Fetret Devri''ni II. Murad değil Çelebi Mehmed sona erdirmiştir. C yanlıştır, bu dönemde toprak kaybı yaşanmış, kazanım değil kayıp söz konusudur. E yanlıştır, Fetret Devri Ankara Savaşı''nın NEDENİ değil SONUCUDUR.');
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('f0b9bf6b-fa68-4291-820b-8d8d2ca9adda', 'Bu dönemde Osmanlı Devleti büyük ölçüde güçlenmiştir.', false, 0);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('f0b9bf6b-fa68-4291-820b-8d8d2ca9adda', 'Bu döneme II. Murad son vermiştir.', false, 1);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('f0b9bf6b-fa68-4291-820b-8d8d2ca9adda', 'Bu dönemde önemli toprak kazanımları elde edilmiştir.', false, 2);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('f0b9bf6b-fa68-4291-820b-8d8d2ca9adda', 'Bu dönem, Ankara Savaşı''nın sonucunda ortaya çıkmış ve Çelebi Mehmed tarafından sona erdirilmiştir.', true, 3);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('f0b9bf6b-fa68-4291-820b-8d8d2ca9adda', 'Fetret Devri, Ankara Savaşı''nın çıkmasına neden olmuştur.', false, 4);
insert into topic_contents (topic_id, summary, content_md, example_question) values ('091291bb-a136-48e2-94b1-8d12631be6ad', 'Mondros Ateşkes Antlaşması sonrası başlayan işgaller, Kuvâ-yi Milliye direnişi, Amasya Genelgesi ile başlayan milli mücadele süreci, Erzurum-Sivas Kongreleri, TBMM''nin açılışı, Doğu-Güney-Batı cephelerindeki savaşlar (İnönü, Sakarya, Büyük Taarruz) ve Lozan Antlaşması ile sonuçlanan süreç bu konunun kronolojik omurgasını oluşturur.', '## Mondros Ateşkes Antlaşması (30 Ekim 1918) ve İşgaller
insert into questions (id, topic_id, difficulty, question_text, kazanim, explanation) values ('eeabb9b7-fb10-4438-9930-949924ca5157', '091291bb-a136-48e2-94b1-8d12631be6ad', 'kolay'::difficulty_level, 'Osmanlı Devleti''nin I. Dünya Savaşı''ndan çekilmesini sağlayan ve İtilaf Devletlerine geniş işgal yetkisi tanıyan antlaşma aşağıdakilerden hangisidir?', 'Mondros Ateşkes Antlaşması''nı bilir.', 'Mondros Ateşkes Antlaşması (30 Ekim 1918), Osmanlı Devleti''ni I. Dünya Savaşı''ndan çıkarmış ve 7. maddesiyle İtilaf Devletlerine güvenliklerini tehdit eden yerleri işgal etme hakkı tanımıştır (C doğru). Sevr (A) bir barış antlaşması taslağıdır ve Mondros''tan sonra hazırlanmıştır. Lozan (B) ve Mudanya (D) Kurtuluş Savaşı''nı sona erdiren belgelerdir. Gümrü (E) Doğu Cephesi''nde Ermenilerle imzalanan bir antlaşmadır.');
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('eeabb9b7-fb10-4438-9930-949924ca5157', 'Sevr Antlaşması', false, 0);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('eeabb9b7-fb10-4438-9930-949924ca5157', 'Lozan Antlaşması', false, 1);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('eeabb9b7-fb10-4438-9930-949924ca5157', 'Mondros Ateşkes Antlaşması', true, 2);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('eeabb9b7-fb10-4438-9930-949924ca5157', 'Mudanya Ateşkes Antlaşması', false, 3);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('eeabb9b7-fb10-4438-9930-949924ca5157', 'Gümrü Antlaşması', false, 4);
insert into questions (id, topic_id, difficulty, question_text, kazanim, explanation) values ('c775b81a-be61-4770-a958-4086ab62c264', '091291bb-a136-48e2-94b1-8d12631be6ad', 'orta'::difficulty_level, 'Kurtuluş Savaşı''nın gerekçesini ve yöntemini belirleyen, ''Milletin bağımsızlığını yine milletin azim ve kararı kurtaracaktır'' ifadesinin yer aldığı belge aşağıdakilerden hangisidir?', 'Amasya Genelgesi''nin önemini bilir.', 'Bu ifade Amasya Genelgesi''nde (22 Haziran 1919) yer alır ve millî egemenlik ilkesinin ilk resmi vurgulandığı belge olması nedeniyle Kurtuluş Savaşı''nın gerekçesi ve yöntemini belirleyen temel metin kabul edilir (B doğru). Erzurum Kongresi (A) bölgesel, Sivas Kongresi (C) millî nitelikli kongrelerdir ve Amasya Genelgesi''nden sonra yapılmıştır. Misak-ı Millî (D) sınırları belirleyen bir karardır. Amasya Görüşmeleri (E) farklı bir aşamadır.');
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('c775b81a-be61-4770-a958-4086ab62c264', 'Erzurum Kongresi kararları', false, 0);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('c775b81a-be61-4770-a958-4086ab62c264', 'Amasya Genelgesi', true, 1);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('c775b81a-be61-4770-a958-4086ab62c264', 'Sivas Kongresi kararları', false, 2);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('c775b81a-be61-4770-a958-4086ab62c264', 'Misak-ı Millî', false, 3);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('c775b81a-be61-4770-a958-4086ab62c264', 'Amasya Görüşmeleri', false, 4);
insert into questions (id, topic_id, difficulty, question_text, kazanim, explanation) values ('139f3c60-21c5-4b5c-b10a-a3e8d73b1bab', '091291bb-a136-48e2-94b1-8d12631be6ad', 'orta'::difficulty_level, 'TBMM''nin açılmasına doğrudan zemin hazırlayan gelişme aşağıdakilerden hangisidir?', 'TBMM''nin açılış sürecini bilir.', 'İstanbul''un İtilaf Devletlerince resmen işgal edilmesi (16 Mart 1920) ve Mebusan Meclisi''nin kapatılması üzerine, milli iradeyi temsil edecek yeni bir meclise duyulan ihtiyaçla Ankara''da TBMM açılmıştır (23 Nisan 1920) (D doğru). A, B ve C''deki olaylar TBMM açıldıktan SONRA gerçekleşmiştir. E''deki Sivas Kongresi TBMM''nin açılışından önce olsa da açılışın DOĞRUDAN nedeni değildir; doğrudan neden İstanbul''un işgalidir.');
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('139f3c60-21c5-4b5c-b10a-a3e8d73b1bab', 'I. İnönü Muharebesi''nin kazanılması', false, 0);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('139f3c60-21c5-4b5c-b10a-a3e8d73b1bab', 'Sakarya Meydan Muharebesi''nin kazanılması', false, 1);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('139f3c60-21c5-4b5c-b10a-a3e8d73b1bab', 'Lozan Antlaşması''nın imzalanması', false, 2);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('139f3c60-21c5-4b5c-b10a-a3e8d73b1bab', 'İstanbul''un işgal edilmesi ve Mebusan Meclisi''nin kapatılması', true, 3);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('139f3c60-21c5-4b5c-b10a-a3e8d73b1bab', 'Sivas Kongresi''nin toplanması', false, 4);
insert into questions (id, topic_id, difficulty, question_text, kazanim, explanation) values ('52aec63b-fefc-4d40-be9b-b136beb5a7ae', '091291bb-a136-48e2-94b1-8d12631be6ad', 'zor'::difficulty_level, 'Lozan Antlaşması ile ilgili aşağıdaki bilgilerden hangisi doğrudur?', 'Lozan Antlaşması''nın kazanımlarını ve çözülemeyen sorunlarını değerlendirir.', 'Lozan Antlaşması''nda kapitülasyonlar tamamen kaldırılmış olsa da Musul ve Boğazlar sorunları TAM olarak çözülememiş, bu sorunlar ileriki yıllara (Musul için 1926 Ankara Antlaşması, Boğazlar için 1936 Montrö Sözleşmesi) bırakılmıştır (C doğru). A yanlıştır, Lozan bir ateşkes değil BARIŞ antlaşmasıdır (ateşkes Mudanya''dır). B yanlıştır, kapitülasyonlar kısmen değil TAMAMEN kaldırılmıştır. D yanlıştır, Musul sorunu Lozan''da çözülmemiştir. E yanlıştır, Türkiye''nin bağımsızlığı Lozan ile uluslararası alanda TANINMIŞTIR, aksi doğru değildir.');
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('52aec63b-fefc-4d40-be9b-b136beb5a7ae', 'Lozan, Kurtuluş Savaşı''nı sona erdiren bir ateşkes antlaşmasıdır.', false, 0);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('52aec63b-fefc-4d40-be9b-b136beb5a7ae', 'Kapitülasyonlar kısmen kaldırılmış, bazı ayrıcalıklar devam etmiştir.', false, 1);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('52aec63b-fefc-4d40-be9b-b136beb5a7ae', 'Musul ve Boğazlar sorunları tam çözülemeyip sonraki yıllara bırakılmıştır.', true, 2);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('52aec63b-fefc-4d40-be9b-b136beb5a7ae', 'Musul sorunu bu antlaşmayla kesin olarak Türkiye lehine çözülmüştür.', false, 3);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('52aec63b-fefc-4d40-be9b-b136beb5a7ae', 'Bu antlaşmayla Türkiye''nin bağımsızlığı uluslararası alanda tanınmamıştır.', false, 4);
insert into topic_contents (topic_id, summary, content_md, example_question) values ('3c087fbc-2d70-4b75-880e-8e2f9e4475fb', 'Cumhuriyetin ilanı ve halifeliğin kaldırılmasıyla başlayan siyasi inkılaplar; Medeni Kanun''un kabulüyle hukuk alanındaki köklü değişim; Tevhid-i Tedrisat ve harf inkılabıyla eğitim-kültür alanındaki dönüşüm; İzmir İktisat Kongresi ve aşar vergisinin kaldırılmasıyla ekonomik atılım; kadınlara siyasi hakların tanınmasıyla toplumsal inkılaplar bu konunun beş temel alt başlığıdır.', '## Siyasi İnkılaplar
insert into questions (id, topic_id, difficulty, question_text, kazanim, explanation) values ('2aa8e743-ebdb-43cd-b861-0fa83ac78809', '3c087fbc-2d70-4b75-880e-8e2f9e4475fb', 'kolay'::difficulty_level, 'Cumhuriyetin ilan edildiği tarih ve ilk Cumhurbaşkanı aşağıdakilerden hangisinde doğru verilmiştir?', 'Cumhuriyetin ilanını bilir.', 'Cumhuriyet 29 Ekim 1923''te ilan edilmiş ve Mustafa Kemal ilk Cumhurbaşkanı seçilmiştir (B doğru). Diğer seçeneklerdeki tarihler (3 Mart 1924 halifeliğin kaldırılması, 1926 Medeni Kanun, 1928 Harf İnkılabı, 1934 kadınlara seçme-seçilme hakkı) farklı inkılaplara aittir ve Cumhuriyetin ilan tarihiyle karıştırılmamalıdır.');
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('2aa8e743-ebdb-43cd-b861-0fa83ac78809', '3 Mart 1924 - Mustafa Kemal', false, 0);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('2aa8e743-ebdb-43cd-b861-0fa83ac78809', '29 Ekim 1923 - Mustafa Kemal', true, 1);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('2aa8e743-ebdb-43cd-b861-0fa83ac78809', '1926 - İsmet İnönü', false, 2);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('2aa8e743-ebdb-43cd-b861-0fa83ac78809', '1928 - Mustafa Kemal', false, 3);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('2aa8e743-ebdb-43cd-b861-0fa83ac78809', '1934 - İsmet İnönü', false, 4);
insert into questions (id, topic_id, difficulty, question_text, kazanim, explanation) values ('e7682692-4828-4a0f-bdab-26aa1703b864', '3c087fbc-2d70-4b75-880e-8e2f9e4475fb', 'orta'::difficulty_level, 'Aşağıdakilerden hangisi 3 Mart 1924 tarihinde gerçekleşen iki önemli gelişmeden biri değildir?', 'Aynı tarihte gerçekleşen inkılapları ayırt eder.', 'Medeni Kanun''un kabulü 1926 yılında gerçekleşmiştir, 3 Mart 1924''te DEĞİL (C doğru, gerçekleşmeyen). Halifeliğin kaldırılması (A) ve Tevhid-i Tedrisat Kanunu''nun kabulü (B) aynı gün, 3 Mart 1924''te gerçekleşmiştir. Şer''iye ve Evkaf Vekaleti''nin kaldırılması (D) ile Erkân-ı Harbiye-i Umumiye Vekaleti''nin kaldırılması (E) da aynı gün alınan kararlar arasındadır.');
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('e7682692-4828-4a0f-bdab-26aa1703b864', 'Halifeliğin kaldırılması', false, 0);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('e7682692-4828-4a0f-bdab-26aa1703b864', 'Tevhid-i Tedrisat Kanunu''nun kabulü', false, 1);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('e7682692-4828-4a0f-bdab-26aa1703b864', 'Türk Medeni Kanunu''nun kabulü', true, 2);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('e7682692-4828-4a0f-bdab-26aa1703b864', 'Şer''iye ve Evkaf Vekaleti''nin kaldırılması', false, 3);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('e7682692-4828-4a0f-bdab-26aa1703b864', 'Erkân-ı Harbiye-i Umumiye Vekaleti''nin kaldırılması', false, 4);
insert into questions (id, topic_id, difficulty, question_text, kazanim, explanation) values ('6fd0a121-e382-47e2-b1d8-f7ba73ca0f0b', '3c087fbc-2d70-4b75-880e-8e2f9e4475fb', 'orta'::difficulty_level, 'Kadınlara milletvekili seçme ve seçilme hakkının tanındığı yıl aşağıdakilerden hangisidir?', 'Kadın haklarındaki kademeli gelişimi bilir.', 'Kadınlara milletvekili seçme ve seçilme hakkı 1934''te tanınmıştır (D doğru); bu hak, belediye (1930) ve muhtarlık (1933) seçimlerindeki haklardan sonra en geniş kapsamlı olanıdır. 1923 (A), 1926 (B) ve 1930 (C) bu son aşamadan önceki farklı gelişmelere ait tarihlerdir; 1930''da yalnızca belediye seçimlerinde hak tanınmıştı, milletvekilliği değil.');
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('6fd0a121-e382-47e2-b1d8-f7ba73ca0f0b', '1923', false, 0);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('6fd0a121-e382-47e2-b1d8-f7ba73ca0f0b', '1926', false, 1);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('6fd0a121-e382-47e2-b1d8-f7ba73ca0f0b', '1930', false, 2);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('6fd0a121-e382-47e2-b1d8-f7ba73ca0f0b', '1934', true, 3);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('6fd0a121-e382-47e2-b1d8-f7ba73ca0f0b', '1938', false, 4);
insert into questions (id, topic_id, difficulty, question_text, kazanim, explanation) values ('258257dc-6234-4625-9aba-f3c6cdc5fa87', '3c087fbc-2d70-4b75-880e-8e2f9e4475fb', 'zor'::difficulty_level, 'Aşar vergisinin kaldırılması (1925) ile ilgili aşağıdaki yargılardan hangisi doğrudur?', 'Ekonomik inkılapları toplumsal/siyasi inkılaplardan ayırt eder.', 'Aşar vergisinin kaldırılması, üretim üzerinden alınan ağır bir Osmanlı vergisini ortadan kaldırarak çiftçinin ekonomik yükünü azaltmayı amaçlayan EKONOMİK bir inkılaptır (B doğru). A yanlıştır, bu bir toplumsal değil ekonomik inkılaptır. C yanlıştır, bu adım köylüyü/çiftçiyi rahatlatmıştır, zorlaştırmamıştır. D yanlıştır, kaldırılan bir üretim vergisidir, gümrük vergisi değildir. E yanlıştır, bu düzenleme Cumhuriyetin ilanından SONRA (1925) yapılmıştır, Kurtuluş Savaşı sırasında değil.');
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('258257dc-6234-4625-9aba-f3c6cdc5fa87', 'Bu, toplumsal alanda yapılan bir inkılaptır.', false, 0);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('258257dc-6234-4625-9aba-f3c6cdc5fa87', 'Bu, çiftçinin ekonomik yükünü azaltmayı amaçlayan ekonomik bir inkılaptır.', true, 1);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('258257dc-6234-4625-9aba-f3c6cdc5fa87', 'Bu düzenleme köylünün vergi yükünü artırmıştır.', false, 2);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('258257dc-6234-4625-9aba-f3c6cdc5fa87', 'Aşar, dış ticaretten alınan bir gümrük vergisidir.', false, 3);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('258257dc-6234-4625-9aba-f3c6cdc5fa87', 'Bu düzenleme Kurtuluş Savaşı sırasında yapılmıştır.', false, 4);
insert into topics (id, subject_id, name, slug, kazanim_text, weight, order_index) values ('44672589-4a32-4299-951a-afa51d7c3099', '0074c5df-5b70-4274-9235-a8fcfb386791', 'İlk Türk-İslam Devletleri', 'ilk-turk-islam-devletleri', 'Türklerin İslamiyet''i kabul sürecini ve ilk Türk-İslam devletlerinin (Karahanlı, Gazneli, Büyük Selçuklu, Anadolu Selçuklu) özelliklerini bilir.', 1.0, 5);
insert into topic_contents (topic_id, summary, content_md, example_question) values ('44672589-4a32-4299-951a-afa51d7c3099', 'Talas Savaşı ile başlayan Türk-Arap yakınlaşması sonrası Türklerin kitleler hâlinde İslamiyet''i kabul etmesi, ardından kurulan Karahanlı Devleti (ilk Türk-İslam devleti), Gazneliler, Büyük Selçuklu Devleti (Malazgirt Zaferi ile Anadolu''nun kapılarının açılması) ve Anadolu Selçuklu Devleti bu konunun temel yapı taşlarıdır.', '## Talas Savaşı (751) ve İslamiyet''in Kabulü
insert into questions (id, topic_id, difficulty, question_text, kazanim, explanation) values ('a5262f9c-c4db-4566-a5aa-dcbdfc40efa4', '44672589-4a32-4299-951a-afa51d7c3099', 'kolay'::difficulty_level, 'Türklerin Çinlilere karşı Abbasilerin yanında yer alarak Çin''in Orta Asya''daki ilerleyişini durdurduğu ve İslamiyet''in Türkler arasında yayılma sürecini başlatan savaş aşağıdakilerden hangisidir?', 'Talas Savaşı''nın önemini bilir.', 'Talas Savaşı (751), Türklerin (Karluklar) Abbasiler safında Çinlilere karşı savaşmasıyla gerçekleşmiş ve Türk-Arap yakınlaşmasıyla İslamiyet''in Türkler arasında yayılma sürecini başlatmıştır (C doğru). Malazgirt (A) ve Dandanakan (B) daha sonraki Selçuklu dönemi savaşlarıdır. Kösedağ (D) Anadolu Selçuklularının Moğollara yenildiği savaştır. Miryokefalon (E) 1176''da gerçekleşmiş farklı bir savaştır.');
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('a5262f9c-c4db-4566-a5aa-dcbdfc40efa4', 'Malazgirt Savaşı', false, 0);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('a5262f9c-c4db-4566-a5aa-dcbdfc40efa4', 'Dandanakan Savaşı', false, 1);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('a5262f9c-c4db-4566-a5aa-dcbdfc40efa4', 'Talas Savaşı', true, 2);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('a5262f9c-c4db-4566-a5aa-dcbdfc40efa4', 'Kösedağ Savaşı', false, 3);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('a5262f9c-c4db-4566-a5aa-dcbdfc40efa4', 'Miryokefalon Savaşı', false, 4);
insert into questions (id, topic_id, difficulty, question_text, kazanim, explanation) values ('00262069-ea1b-4cb7-91ed-f0bc05b6b443', '44672589-4a32-4299-951a-afa51d7c3099', 'orta'::difficulty_level, '''Sultan'' unvanını halifeden alan ilk Türk-İslam hükümdarı ve devleti aşağıdakilerden hangisinde doğru eşleştirilmiştir?', 'Gazneli Devleti''nin özelliklerini bilir.', 'Gazneli Sultan Mahmud, halifeden ''Sultan'' unvanını alan ilk Türk-İslam hükümdarıdır (B doğru). Satuk Buğra Han (A) Karahanlıların İslamiyet''i kabul eden hükümdarıdır ama sultan unvanı almamıştır. Tuğrul Bey (C) Büyük Selçuklu''nun kurucusudur ve ''sultan'' unvanını Sultan Mahmud''dan sonra almıştır. Alparslan (D) ve Melikşah (E) sonraki Selçuklu hükümdarlarıdır.');
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('00262069-ea1b-4cb7-91ed-f0bc05b6b443', 'Satuk Buğra Han - Karahanlı Devleti', false, 0);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('00262069-ea1b-4cb7-91ed-f0bc05b6b443', 'Sultan Mahmud - Gazneli Devleti', true, 1);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('00262069-ea1b-4cb7-91ed-f0bc05b6b443', 'Tuğrul Bey - Büyük Selçuklu Devleti', false, 2);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('00262069-ea1b-4cb7-91ed-f0bc05b6b443', 'Alparslan - Büyük Selçuklu Devleti', false, 3);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('00262069-ea1b-4cb7-91ed-f0bc05b6b443', 'Melikşah - Büyük Selçuklu Devleti', false, 4);
insert into questions (id, topic_id, difficulty, question_text, kazanim, explanation) values ('3e5cc241-7d76-4c58-b432-e525e6bd282c', '44672589-4a32-4299-951a-afa51d7c3099', 'orta'::difficulty_level, 'Anadolu''nun Türklere açılmasını sağlayan dönüm noktası olan savaş ve hükümdarı aşağıdakilerden hangisinde doğru verilmiştir?', 'Malazgirt Zaferi''nin önemini bilir.', 'Malazgirt Zaferi (1071), Büyük Selçuklu hükümdarı Alparslan tarafından Bizans''a karşı kazanılmış ve Anadolu''nun Türklere açılmasını sağlayan dönüm noktası olmuştur (C doğru). Dandanakan (A, Tuğrul Bey döneminde Gaznelilere karşı kazanılmıştır) ve Talas (B) farklı savaşlardır. Kösedağ (D) ise Anadolu Selçuklularının Moğollara YENİLDİĞİ, gerileme sürecini başlatan bir savaştır. Miryokefalon (E) II. Kılıçarslan döneminde kazanılmış farklı bir zaferdir.');
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('3e5cc241-7d76-4c58-b432-e525e6bd282c', 'Dandanakan Savaşı - Tuğrul Bey', false, 0);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('3e5cc241-7d76-4c58-b432-e525e6bd282c', 'Talas Savaşı - Karluklar', false, 1);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('3e5cc241-7d76-4c58-b432-e525e6bd282c', 'Malazgirt Savaşı - Alparslan', true, 2);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('3e5cc241-7d76-4c58-b432-e525e6bd282c', 'Kösedağ Savaşı - II. Gıyaseddin Keyhüsrev', false, 3);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('3e5cc241-7d76-4c58-b432-e525e6bd282c', 'Miryokefalon Savaşı - II. Kılıçarslan', false, 4);
insert into questions (id, topic_id, difficulty, question_text, kazanim, explanation) values ('37fb1c4a-74d0-4144-a4d6-4fe35a35bfb3', '44672589-4a32-4299-951a-afa51d7c3099', 'zor'::difficulty_level, 'Anadolu Selçuklu Devleti''nin 1243 Kösedağ Savaşı''nda yenilmesinin sonuçlarıyla ilgili aşağıdaki yargılardan hangisi doğrudur?', 'Kösedağ Savaşı''nın sonuçlarını değerlendirir.', 'Kösedağ Savaşı''nda Moğollara yenilen Anadolu Selçuklu Devleti büyük ölçüde zayıflamış, merkezi otoritesini kaybetmiş ve bu durum Anadolu''da çeşitli Türk beyliklerinin (bunlardan biri de daha sonra Osmanlı Devleti''ne dönüşecek olan Osmanlı Beyliği) ortaya çıkmasına zemin hazırlamıştır (D doğru). A yanlıştır, bu yenilgi devleti GÜÇLENDİRMEMİŞ, zayıflatmıştır. B yanlıştır, Nizamiye Medreseleri Büyük Selçuklu döneminde (Melikşah-Nizamülmülk) kurulmuştur, Kösedağ''ın sonucu değildir. C yanlıştır, bu savaş Malazgirt gibi Anadolu''nun Türklere AÇILMASINI değil devletin dağılmasını getirmiştir. E yanlıştır, bu savaş Bizans''a karşı değil Moğollara karşı kaybedilmiştir.');
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('37fb1c4a-74d0-4144-a4d6-4fe35a35bfb3', 'Anadolu Selçuklu Devleti bu zaferle güçlenmiştir.', false, 0);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('37fb1c4a-74d0-4144-a4d6-4fe35a35bfb3', 'Bu savaş sonucunda Nizamiye Medreseleri kurulmuştur.', false, 1);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('37fb1c4a-74d0-4144-a4d6-4fe35a35bfb3', 'Bu savaş, Anadolu''nun Türklere açılmasını sağlamıştır.', false, 2);
